INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('久坐+熬夜老师的高性价比健康方案',(SELECT id FROM skills WHERE name='HowToLiveBetter' LIMIT 1),'[''效率管理'']','2026-10-07','[''很好'']','https://github.com/eternity4719/HowToLiveBetter',NULL,NULL,'用 life-decision-guide 查《高性价比人生指南》：输入真实场景「久坐备课+熬夜的初中老师」，skill 自动定位第 2 节（久坐/熬夜/运动）与第 3 节（精力/睡眠）相关条目，按 成本(钱/时间/毅力)×收益×证据等级 排序。输出 4 条零成本高性价比建议：1) 别久坐，起身动一动（坐最久者死亡风险 2.6 倍，每天 60-75 分钟活动可抵消）2) 爬楼梯/快走攒到每天 4-5 分钟（死亡风险低约四成）3) 熬夜当晚补觉别攒周末（少睡不补风险高约 42%）4) 下午 2 点后别碰咖啡因（少睡 1 小时+）。每条注明第几节第几条可溯源。结论：先做不花钱不挤时间的，再谈长期坚持。','示范案例：验证 skill 核心价值——可溯源、不编数据、按性价比排序。可作为家长答疑/口播视频的素材模板。','https://aka.doubaocdn.com/s/PVxY63Sxmt',NULL);
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('家长回复·计算总出错·文章骨架',(SELECT id FROM skills WHERE name='writing-shape' LIMIT 1),'[''家长答疑'']','2026-10-08','[''很好'']',NULL,'家长问『初一孩子计算总出错、粗心怎么办』，代写回复前先用写作结构搭骨架','[''已验证可复现'']','按 writing-shape 流程：①读家长提问素材；②定前提（家长已知『计算出错』现象，需补归因框架）；③给出 3 个候选开头（共情立论/归因清单/错题场景切入）；④选定『粗心是结果不是原因』角度；⑤逐段搭骨架：共情开场→归因1熟练度不足→归因2过程不规范（跳步/草稿乱）→归因3检查无方法→一周执行表→预期管理','结构让回复告别『你要细心点』式说教，直接落到 3 个可执行归因+一周动作','https://aka.doubaocdn.com/s/SuNhAZVajw','开头角度选择耗时最多；一次给 3 个候选让用户拍板更快');
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('口播稿·刷题没效果三件事·节奏骨架',(SELECT id FROM skills WHERE name='writing-beats' LIMIT 1),'[''口播视频'']','2026-10-08','[''很好'']',NULL,'做『孩子刷题没效果』口播视频，用节奏技能设计节拍序列','[''已验证可复现'']','按 writing-beats：①定前提（家长懂『刷题』）；②候选起始 beat，选定『钩子：刷题没效果不是题量问题』；③逐 beat 推进并检查 grounding：钩子→反转（先归因错题）→第一件事限时训练→第二件事讲题输出→第三件事错题间隔重做→收尾一周计划','口播稿从此有起承转合，不再平铺直叙','https://aka.doubaocdn.com/s/jVRdLyP9YR','beat 间 grounding 检查耗时，每个新概念必须先落地再被引用');
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('10月初中数学内容策略',(SELECT id FROM skills WHERE name='content-strategy' LIMIT 1),'[''内容创作'']','2026-10-08','[''很好'']',NULL,'为口播号+家长答疑号做 10 月内容规划','[''已验证可复现'']','按 content-strategy Before Planning：①业务背景（口播号定位学习方法、答疑号定位家长问题）；②受众调研（初一初二家长，焦虑点=计算/几何/函数/习惯）；③4 个内容支柱：计算基本功/几何入门/函数启蒙/学习习惯；④产出 12 条选题+第一周日历','选题从『我想发什么』变成『家长在焦虑什么』','https://aka.doubaocdn.com/s/IeHnw59PUU','受众调研是重头，素材够才能让选题不空');
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('Skill中心 worker.js 安全审计',(SELECT id FROM skills WHERE name='security-audit' LIMIT 1),'[''效率管理'']','2026-10-08','[''很好'']',NULL,'网页反馈链路 worker.js 上线后做安全自查','[''已验证可复现'']','按 security-audit 审计 backend/worker.js：①硬编码凭据检查；②Origin 校验强度；③速率限制；④token 存储方式；⑤API 容错。逐条对照 checklist 输出发现+修复建议','发现 4 个问题：BASE_TOKEN 常量硬编码在源码、ALLOWED_ORIGIN 仅验 Origin 头可伪造、无速率限制可被刷写库、user token 明文存 KV','https://aka.doubaocdn.com/s/wLKcHBIydo','逐条对照约 5 分钟');
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('沉淀·Base写入与技能安装经验',(SELECT id FROM skills WHERE name='self-improving-agent' LIMIT 1),'[''效率管理'']','2026-10-08','[''很好'']',NULL,'连续踩坑后沉淀可复用经验，避免重复犯错','[''已验证可复现'']','按 self-improving-agent 流程：①回顾既有 learnings；②沉淀 3 条新经验：Base 写入用 --json 扁平 create_records（不要 --create-records flag）；安装技能后要 cp -rL 到 .user_skills 并 tar 备份，否则环境清除会丢；lark-cli 参数以 --help 实测为准','经验落盘后可被后续任务复用，越用越聪明','https://aka.doubaocdn.com/s/nLdYsWZKIL','约 3 分钟');
