INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('一元二次方程解法流程（diagram-design 试跑）',(SELECT id FROM skills WHERE name='diagram-design' LIMIT 1),'[''题目解析'']','2026-10-08','[''很好'']','https://aka.doubaocdn.com/s/W874BHKOYH','验证 diagram-design 能否快速产出编辑级质感的数学方法图解，用于讲解/讲义配图','[''已验证可复现'']','1. 按 skill 流程选择 Flowchart 型（决策逻辑）→ 2. 按 9 节点预算设计 缺常数项/缺一次项/能否因式分解 三分支 → 3. 生成自包含 HTML（设计系统含起止椭圆/判断菱形/解法矩形/推荐主线焦点色）→ 4. 跑 scripts/self_check.py 通过，export_svg.py 导出 SVG','教学图表利器：方法选择类决策图可替代一大段文字，且风格统一可进讲义','https://aka.doubaocdn.com/s/W874BHKOYH','约 12 分钟；主要是节点预算内取舍（>9 节点需拆分）');
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('家长咨询回复改写（i-have-adhd 试跑）',(SELECT id FROM skills WHERE name='i-have-adhd' LIMIT 1),'[''家长答疑'']','2026-10-08','[''很好'']','https://aka.doubaocdn.com/s/sS3kxeMEWF','验证 i-have-adhd 的 ADHD 读者友好规则能否让代写的家长回复更直给、可执行','[''已验证可复现'']','1. 输入家长原话（孩子月考 78 分退步、作业能完成考试考不好怎么办）→ 2. 按规则改写：首行给可执行动作（拍卷子 6 题）、编号三步诊断法、结尾给 2 分钟内的单一动作、删寒暄铺垫 → 3. 产出结论先行版回复','家长沟通提效明显：同一内容信息密度更高，家长读完知道下一步做什么',NULL,'约 5 分钟；关键是克制——把''您别着急''这类安慰全删掉');
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('Claude Code 技能开发检索（everything-claude-code 试跑）',(SELECT id FROM skills WHERE name='everything-claude-code' LIMIT 1),'[''效率管理'']','2026-10-08','[''很好'']','https://aka.doubaocdn.com/s/0TLqqxmdC1','验证 everything-claude-code 知识库能否快速回答''Claude Code 里怎么做技能''这类问题','[''已验证可复现'']','1. 克隆仓库做库内检索 → 2. 命中 docs/es/commands/skill-create.md 与 MANUAL-ADAPTATION-GUIDE.md → 3. 得出可执行结论：本地可用 /skill-create 解析 git 历史生成 SKILL.md，含 --commits/--output/--instincts 参数；跨环境迁移遵循''最小上下文包''原则','研究型资料库：当 Claude Code 的''说明书''用，遇到问题先查它再搜',NULL,'约 8 分钟；库很大需定向检索，直接问比翻目录快');
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('Claude Code 生态技能清单检索（awesome-claude-code 试跑）',(SELECT id FROM skills WHERE name='awesome-claude-code' LIMIT 1),'[''效率管理'']','2026-10-08','[''很好'']','https://aka.doubaocdn.com/s/EhXBfbtWM3','验证 awesome-claude-code 清单能否帮老师找到教育/文档类现成 Claude Code 技能','[''已验证可复现'']','1. 克隆仓库 → 2. 检索 Documentation, Knowledge & Learning 与 Writing & Prose Quality 板块 → 3. 命中 learn-faster-kit（FASTER 自主学习框架，可给学生做计划）、showreel（自动生成图文文档/录屏说明）、claude-code-docs（官方文档全文本检索镜像）','找现成技能的第一站：先查清单再决定装什么，避免重复造轮子',NULL,'约 6 分钟；清单分类清晰，按板块扫即可');
