INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('勾股定理证明动画方案（math-to-manim 试跑）',(SELECT id FROM skills WHERE name='math-to-manim' LIMIT 1),'[''口播视频'']','2026-10-08','[''很好'']','https://aka.doubaocdn.com/s/dDVRUimUom','验证 math-to-manim 技能工作流能否在用户业务场景（初中数学教学/口播/家长沟通）直接产出可用成果','[''已验证可复现'']','1. 叙事弧：面积差→c²=a²+b² 2. 几何先呈现（三边正方形）3. 面积对比揭示公式 4. 先 deterministic check 再抽帧目检','证明题用面积差比代数推导直观，M2M2 流水线可复用',NULL,NULL);
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('负数的认识知识漫画（baoyu-comic 打磨）',(SELECT id FROM skills WHERE name='baoyu-comic' LIMIT 1),'[''教学备课'']','2026-10-08','[''很好'']','https://aka.doubaocdn.com/s/mUXYQmaheb','七年级上册有理数§1.1负数的认识，家长/学生痛点：负数从哪来、0是正是负、负数比较。用知识漫画把概念讲成故事。','[''已验证可复现'']','EXTEND.md首设(ligne-claire+warm) → 分析/分镜(5页:引入→数轴→应用→总结) → 角色表(小明+数轴精灵) → 按页prompt+角色表ref批量出图 → 评审4问题迭代P3/P4 → 合并PDF','2026-10-08 Skill Lab 第4单定稿：三版迭代(清线→水墨→瑞士网格)，用户选定瑞士网格转正。瑞士网格版=白底细网格+无衬线大排版+红色几何强调+16:9横版，撤漫画分镜改网格分区，教学考点全保留(0分界性/负数比较/相反意义)。此前水墨版见 https://aka.doubaocdn.com/s/h7BEhGdkhB ，清线版对比见 https://aka.doubaocdn.com/s/YU5MtQojNN 。',NULL,NULL);
INSERT INTO cases(name,skill_id,scene,date,effect,link,bg,repro,steps,note,cover,time) VALUES('正数与负数第1课时课件（ppt-master 打磨）',(SELECT id FROM skills WHERE name='ppt-master' LIMIT 1),'[''教学备课'']','2026-10-08','[''未验收'']','https://aka.doubaocdn.com/s/RyymVwZZ6p','Skill Lab 第5单：打磨 ppt-master 生成教学课件，与 baoyu-comic 瑞士网格版同视觉语言，形成漫画预习→课件讲授系列','[''已验证可复现'']','1)项目初始化 project_manager.py init --format ppt169 2)写源内容source.md(10页教学结构) 3)写design_spec.md+spec_lock.md(瑞士网格/墨蓝#1B3A6B/红#C8102E/Noto Sans CJK) 4)启动live preview 5)SVG逐页手写(1280x720,网格底纹+大标题+编号章节标签) 6)svg_quality_checker质量门通过 7)svg_to_pptx.py转PPTX','踩坑记录:1)canvas格式名是ppt169不是16:9 2)import-sources路径要精确到projects/<name>_ppt169_日期 3)release导出需spec_lock.md+质量报告 4)spec_lock必须声明所有实际用到的字号角色(title52/body28/annotation22/caption24/lead30等),否则font-size recurrence报错 5)design_spec §IX Slide块格式:### Slide NN纯数字+每块必带-Audience move: 6)P3卡片280px宽文字溢出→改2x2网格580宽 7)P5分类行x坐标重叠→改上下两行','https://aka.doubaocdn.com/s/6qEzVGMPpV',NULL);
