INSERT INTO handbook(skill_id,goal,prompt,steps,examples) VALUES((SELECT id FROM skills WHERE name='Anthropic-Cybersecurity-Skills' LIMIT 1),NULL,'用 Anthropic-Cybersecurity-Skills 给这个网页做一次安全自查','待检测的网页/代码/目标','安全评估/攻防分析报告');
INSERT INTO handbook(skill_id,goal,prompt,steps,examples) VALUES((SELECT id FROM skills WHERE name='Auto-claude-code-research-in-sleep' LIMIT 1),NULL,'用 ARIS 调研 <主题>，跑一轮找方向+复现，并让另一个模型复核结论','一个明确的研究方向/问题；被执行 agent 与复核 agent 各自可用的模型（默认 Codex MCP 复核）','Markdown 研究报告 + 可跑代码 + 复核意见（工作流产物，非现成平台）');
INSERT INTO handbook(skill_id,goal,prompt,steps,examples) VALUES((SELECT id FROM skills WHERE name='AI-Research-SKILLs' LIMIT 1),NULL,'用 AI-Research-SKILLs 里的 <某类技能> 完成 <任务>','明确要做的技术环节（如微调/RAG/评测）；对应环境依赖（GPU、框架）','按技能分类的流程 / 代码 / 报告');
INSERT INTO handbook(skill_id,goal,prompt,steps,examples) VALUES((SELECT id FROM skills WHERE name='anything2explainer' LIMIT 1),NULL,'用 anything2explainer 把 <知识点/文章> 做成 <时长/语言> 的解说视频','主题或现成文稿；时长与语言；TTS 音色（自带 kokoro 或对接火山 TTS 2.0）','1280×720 H.264 MP4（配音+字幕+章节进度条）+ 研究稿/分镜/QC 报告等全套中间产物');
INSERT INTO handbook(skill_id,goal,prompt,steps,examples) VALUES((SELECT id FROM skills WHERE name='huashu-design' LIMIT 1),NULL,'用 huashu-design 做一张 <主题> 的信息图 / 一套 <主题> 的 PPT / 一段 <主题> 发布动画','一个主题或文案；可选投喂品牌资产（logo、色板、UI 截图）让产出更贴品牌','HTML 原生设计稿（可导出 PPT、动画 MP4、信息图等）');
INSERT INTO handbook(skill_id,goal,prompt,steps,examples) VALUES((SELECT id FROM skills WHERE name='agent-skills' LIMIT 1),NULL,'用 agent-skills 先 /spec 把需求写成规格，再 /plan 拆分，然后 /build 实现','一个开发需求；项目代码仓','规格文档、任务计划、增量提交的代码与测试');
