INSERT INTO polish(name,scene,status,rounds,score,issues,fixes,tpl,note,date) VALUES('archify','一元二次方程解法流程图','已达标','3','4.5','v1：①无视觉规格（默认 classic）②无教学副标题 ③图例工程语义硬映射 ④cards 字段用 body（应为 dot/title/items）导致卡片异常。v2 初版：同 lane 同 col 节点重叠、sublabel 超宽超桌面预算、viewBox 1159px 超 930px（6px 字缩到 4.8px 不可读）','①指定 editorial 视觉预设+subtitle 教学语境 ②图例改教学语义（起点/判断/快捷解法/结果）③cards 修正为 dot/title/items ④sublabel 精简到 12 字符内、yOffset 90 错开同列节点、按 v1 成功布局对齐 col','archify 教学图配方：meta.visual_preset=editorial（教学展示首选）；meta.subtitle 写教学语境；node 字段用 type/sublabel/icon（勿用 kind/description/body）；判断与解法各占独立 col；同 lane 同列节点用 yOffset 错开；sublabel ≤12 字符；viewBox 目标 ≤930px 过 desktop-readability 门；cards 用 dot/title/items 结构','v1 在旧版本（无 desktop-readability 门）下生成；v2 通过 archify 3.0.1 全部质量门 validate/deliver/check/browser-check；editorial 预设自带编辑风格切换与现场笔记','2026-10-08');
INSERT INTO polish(name,scene,status,rounds,score,issues,fixes,tpl,note,date) VALUES('manim-video','三角形内角和定理证明动画','已达标','1','4.3','1)辅助线透明度0.75过高,结构层抢主角(标准0.15-0.35) 2)角弧无∠A/∠B/∠C角标,学生难对应 3)Aha平角出现平淡,180°直接FadeIn无强调 4)结论公式单色,与前面场景颜色无呼应 5)四场景布局单一(FULL_CENTER) 6)角搬走后原位置无残影,搬运感弱','1)辅助线opacity降到0.35(结构层) 2)补三色角标∠A(黄)/∠B(蓝)/∠C(绿) 3)平角后180°用GrowFromCenter弹出+三弧加粗高亮 4)结论公式三色MathTex(A黄/B蓝/C绿) 5)Scene2三角偏左下,每场景布局不同 6)角搬运保留原位置残影(0.4)','1)叙事弧先行:先定Aha时刻再写代码 2)三色贯穿全片(A/B/C角固定色,结论公式同色呼应) 3)结构元素(辅助线/网格)opacity≤0.35 4)关键揭示后wait 2.5-3s 5)角标、等式用与弧同色Text(中文字体Noto Sans CJK SC) 6)每场景不同布局/入场动画 7)渲染:草稿-ql(5-15s/场景),成片-qm 720p30(教学够用) 8)字幕subcaption每动画必带','v1用平行线+内错角标准证明法(人教版七下),说明页与成片方法已对齐;成片42.8s带字幕','2026-10-08');
INSERT INTO polish(name,scene,status,rounds,score,issues,fixes,tpl,note,date) VALUES('math-to-manim','勾股定理证明动画','已达标','2','4.4','1)v1无字幕,学生跟不上 2)证明是静态面积对比,无Aha揭示 3)三边正方形与边长标签无颜色对应 4)62.5s偏长,节奏拖 5)无角标/直角标记细节 6)Scene3拼图几何用描边三角+透明度叠加,视觉平淡','1)全片subcaption字幕 2)改为经典4三角双拼法:同一大正方形两种拼法(左c²斜放/右a²+b²),空白面积相等作Aha 3)三色贯穿:a蓝/b绿/c黄,正方形同色 4)压缩到51s 5)Scene1补直角标记+边长标签 6)三角填充色0.18+空白区高亮0.4','1)题→动画先定证明方法(几何拼图优先于代数) 2)同一图形两种摆法的面积对比=最强Aha 3)c²斜放方块用4条斜边中点构造(Polygon四中点)保证几何精确 4)3-4-5直角三角是教学安全组合(整数网格) 5)公式着色用独立MathTex拼VGroup,勿用[0][i]索引(get_part_by_tex易None) 6)每场景独立class+字幕,成片720p30','复用manim-video打磨模板(三色/字幕/透明度/布局);math-to-manim价值=题→动画推理链,渲染质量按manim-video标准执行;hermes-learns-manim已归档,实际产出走manim渲染','2026-10-08');
INSERT INTO polish(name,scene,status,rounds,score,issues,fixes,tpl,note,date) VALUES('baoyu-comic','《负数的秘密》知识漫画(七年级有理数·负数的认识)','已达标','3','4.6','1)P3天平砝码负号被AI吞掉(写3/1) 2)P3电梯按钮出现下一层竖排怪字 3)P4笔记卡漏也字(0不是正数不是负数) 4)P4背景数轴刻度乱(-3 0 -2 -1 -3) 5)v1出图第2批漏传width导致P3/P4变成1:1方形 6)重生成P1分格退化(3格变4格,0冰点高亮未实现)','1)P3天平砝码负号3次丢失→主信息用数轴+比较式-3<-1<0<1双保险承载 2)漏传width出正方形→16:9必须显式width=1920 height=1080 3)瑞士网格版撤漫画分镜改网格分区(白底细网格/无衬线/红色强调) 4)【转正】用户选定瑞士网格为最终风格：学术海报感、适配课件/公众号/教辅','1)知识漫画选题=单一难点+生活化叙事(负数=温度/欠账/电梯/海拔) 2)先建EXTEND.md(ligne-claire+warm+zh)再开工 3)角色表先行,页面以角色表为ref保一致(image_edit传ref) 4)每页prompt存prompts/NN-*.md可复现 5)AI文字易错:关键规则式在画面出现2次(图中+字幕条),数字负号单独强调 6)3:4竖版直接可用家长群/课堂 7)分格数在prompt里写死(上中下3格/2×2)','第4单 baoyu-comic 最终定稿=瑞士网格版。三轮迭代：清线v1→水墨整本重做→瑞士网格转正。风格升级路径验证：同一skill可通过风格矩阵做出从儿童读物到学术海报的跨度。','2026-10-08');
INSERT INTO polish(name,scene,status,rounds,score,issues,fixes,tpl,note,date) VALUES('ppt-master','初中数学《正数与负数》第1课时课件','已达标','1','4.4','1)卡片宽度不足文字溢出 2)分类行文字横向重叠 3)spec_lock字号角色未声明触发质量门 4)design_spec IX Slide块格式不符 5)flat模式文字栅格化(Office兼容PNG+SVG双格式,可编辑性受限)','1)四卡片改2x2网格(580px宽) 2)分类行改上下两行(y=448/498) 3)spec_lock声明title52/body28/lead30/annotation22/caption24等字号角色 4)Slide块用纯数字编号+Audience move 5)质量门全通过后导出','PPT类技能打磨:①canvas格式名用ppt169/ppt43 ②SVG手写前先启动live preview ③spec_lock声明全部字号角色(否则quality checker硬报错) ④设计稿先chromium渲染目检再转PPTX ⑤瑞士网格风格可复用(网格底纹+大标题+编号标签+红强调)','第5单完成。产出可下载PPTX(10页,38KB)。与baoyu-comic瑞士网格版形成视觉系列。下一轮可升级structured模式实现文字可编辑(需补masters/layouts定义)。','2026-10-08');
